program_code='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    rectangles = []
    for r1 in range(h - 2):
        for r2 in range(r1 + 2, h):
            for c1 in range(w - 2):
                for c2 in range(c1 + 2, w):
                    color = g[r1][c1]
                    if g[r1][c1:c2 + 1] != [color] * (c2 - c1 + 1):
                        continue
                    if g[r2][c1:c2 + 1] != [color] * (c2 - c1 + 1):
                        continue
                    if any(g[r][c1] != color or g[r][c2] != color
                           for r in range(r1, r2 + 1)):
                        continue
                    interior = [g[r][c] for r in range(r1 + 1, r2)
                                for c in range(c1 + 1, c2)]
                    if not interior or interior[0] == color or any(
                            value != interior[0] for value in interior):
                        continue
                    fill = 7 if (r2 - r1 + 1) % 2 else 2
                    rectangles.append((r1, r2, c1, c2, fill))
    for r1, r2, c1, c2, fill in rectangles:
        for r in range(r1 + 1, r2):
            for c in range(c1 + 1, c2):
                g[r][c] = fill
    return g
'''
